#!/usr/bin/perl
# Differential tester: C++ test20_executable vs the Rust port.
#
#   difftest.pl <mode> <rounds> [seed]
#
# Modes: uniform extreme mixed tiny huge negative special ties hue strings all
# Each round feeds one batch of RGB triples to both binaries and compares
# stdout (and stderr) byte-for-byte.
use strict;
use warnings;

my $CPP  = "/workspace/dataset/test20_executable";
my $RUST = "/output/test20";

my ($mode, $rounds, $seed) = @ARGV;
$mode   //= "all";
$rounds //= 100;
$seed   //= 0;
srand($seed);

my @ALL = qw(uniform extreme mixed tiny huge negative special ties hue strings);

my @SPECIAL = (0, -0.0, 1, -1, 0.5, 2, -2, 1e-7, 255, 1/3, 2/3,
               0.9999999, 1.0000001, 1e-8, 3e-8, 0.25, 0.75, 1e-9);
my @STRINGS = (
    "0", "0.0", "-0", "-0.0", "1", "1.", ".5", "+.5", "  0.25", "0.5xyz",
    "1e-1", "1E-1", "0x1p-2", "0x.8p0", "0X1.4P1", "0x10p-5", "0x0p0",
    "inf", "-inf", "INF", "Infinity", "nan", "-nan", "NAN", "nan(0x1)",
    "1_0", "0.30000000000000004", "3.4028235e38", "1.1754944e-38",
    "0.1", "0.7", "12345678901234567890", "0.000001", "1e0", "5e-1", "-1e1",
    "0.9999999999999999", "1e-5", "0.0000001", "-0x1.8p-3", "+0", "  -0.5  ",
);

sub rnd { return rand(); }

sub gen {
    my ($m) = @_;
    if ($m eq "uniform")  { return rnd(); }
    if ($m eq "extreme")  { return $SPECIAL[int(rnd() * scalar @SPECIAL)]; }
    if ($m eq "mixed") {
        my $r = rnd();
        return rnd()                 if $r < 0.5;
        return rnd() * 5 - 2         if $r < 0.7;
        return $SPECIAL[int(rnd() * scalar @SPECIAL)] if $r < 0.85;
        return (rnd() * 2 - 1) * 1e6;
    }
    if ($m eq "tiny")     { return (rnd() < 0.5 ? -1 : 1) * 10 ** (-37 + rnd() * 32); }
    if ($m eq "huge")     { return (rnd() < 0.5 ? -1 : 1) * 10 ** (5 + rnd() * 32); }
    if ($m eq "negative") { return -rnd() * 5; }
    if ($m eq "ties")     { return (0.25, 0.5, 0.75, 0, 1, 0.5, 0.25)[int(rnd() * 7)]; }
    if ($m eq "hue") {
        # Hues that land on the hue2rgb sector boundaries (0/120/240/360).
        my @v = (0, 1, 0.5, rnd());
        return $v[int(rnd() * 4)];
    }
    return rnd();
}

sub spell {
    my ($m) = @_;
    return $STRINGS[int(rnd() * scalar @STRINGS)] if $m eq "strings";
    if ($m eq "special") {
        my @s = ("nan", "inf", "-inf", "0", "-0", "1", "0.5", "-0.5", "nan", "inf");
        return $s[int(rnd() * scalar @s)];
    }
    my $v = gen($m);
    my $style = rnd();
    return sprintf("%.17g", $v) if $style < 0.35;
    return sprintf("%.9g",  $v) if $style < 0.65;
    return sprintf("%.7f",  $v) if $style < 0.8;
    return sprintf("%e",    $v) if $style < 0.9;
    return sprintf("%.20g", $v);
}

sub run {
    my ($cmd, @args) = @_;
    my @q = map { my $s = $_; $s =~ s/'/'\\''/g; "'$s'" } @args;
    my $line = "$cmd " . join(" ", @q);
    my $out = `$line 2>/tmp/dt_err.$$`;
    my $rc = $?;
    local $/;
    open(my $fh, "<", "/tmp/dt_err.$$") or return ($rc, $out, "");
    my $err = <$fh>;
    close $fh;
    return ($rc, $out, defined($err) ? $err : "");
}

my $fails = 0;
my @modes = ($mode eq "all") ? @ALL : ($mode);

for my $it (1 .. $rounds) {
    my $m = $modes[int(rnd() * scalar @modes)];
    my $n = (1 + int(rnd() * 12)) * 3;
    my @args = map { spell($m) } (1 .. $n);

    my ($rc_c, $out_c, $err_c) = run($CPP,  @args);
    my ($rc_r, $out_r, $err_r) = run($RUST, @args);

    if ($out_c ne $out_r || $err_c ne $err_r) {
        $fails++;

1	//! Colour-space conversions.
2	//!
3	//! Everything is deliberately written as single-precision expressions in the
4	//! same association order as the C++ original: the observable output is printed
5	//! with six significant digits, but values such as `0.615f*r - 0.515f*g -
6	//! 0.100f*b` for pure white land on `2.23517e-08` rather than `0`, so the
7	//! rounding of every intermediate matters.
