11	/// `std::max(a, b)` — returns `a` when the comparison is unordered.
12	#[inline]
13	fn max2(a: f32, b: f32) -> f32 {
14	    if a < b {
15	        b
16	    } else {
17	        a
18	    }
19	}
20	
21	/// `std::min(a, b)` — returns `a` when the comparison is unordered.
22	#[inline]
23	fn min2(a: f32, b: f32) -> f32 {
24	    if b < a {
25	        b
26	    } else {
27	        a
28	    }
29	}
30	
31	/// `std::max(std::max(r, g), b)`
32	///
33	/// The association matters: `std::max` returns its *first* argument when the
34	/// comparison is unordered, so a NaN channel is swallowed or propagated
35	/// depending on where the fold starts.
36	#[inline]
37	fn max3(r: f32, g: f32, b: f32) -> f32 {
38	    max2(max2(r, g), b)
39	}
40	
41	/// `std::min(std::min(r, g), b)`
42	#[inline]
43	fn min3(r: f32, g: f32, b: f32) -> f32 {
44	    min2(min2(r, g), b)
45	}
46	
47	/// Clamp into `[0, 1]`; NaN propagates, matching `std::min(std::max(v, 0), 1)`.
48	#[inline]
49	fn clamp01(v: f32) -> f32 {
50	    min2(max2(v, 0.0), 1.0)
51	}
52	
53	/// `a + b`, with `a`'s NaN surviving when both operands are NaN.
54	///
55	/// IEEE addition is commutative for every non-NaN input, so this pins down
56	/// exactly one thing: which NaN — and therefore which *sign* — comes out, since
57	/// `std::cout` prints `nan` or `-nan` accordingly. On x86 `addss` returns its
58	/// destination operand when both are NaN, and the C++ compiler's choice of
59	/// destination is what this reproduces.
60	#[inline]
61	fn add_keep_lhs_nan(a: f32, b: f32) -> f32 {
62	    if a.is_nan() {
63	        a
64	    } else if b.is_nan() {
65	        b
66	    } else {
67	        a + b
68	    }
69	}
70	
71	/// `(t1 + t2) + t3` as the C++ compiler emitted the all-addition dot products:
72	/// the third product is the destination of the final add, so its NaN wins over
73	/// the first term's, which in turn wins over the second's. Bit-identical to a
74	/// plain left-to-right sum whenever no operand is NaN.
75	#[inline]
76	fn sum3(t1: f32, t2: f32, t3: f32) -> f32 {
77	    add_keep_lhs_nan(t3, add_keep_lhs_nan(t1, t2))
78	}
