80	/// Hue sector of the max channel, in units of 60 degrees.
81	#[inline]
82	fn hue_sector(c: &RGB, max: f32, d: f32) -> f32 {
83	    if max == c.r {
84	        (c.g - c.b) / d + if c.g < c.b { 6.0 } else { 0.0 }
85	    } else if max == c.g {
86	        (c.b - c.r) / d + 2.0
87	    } else {
88	        (c.r - c.g) / d + 4.0
89	    }
90	}
91	
92	/// Hue in degrees.
93	///
94	/// The sector is first normalised into `[0, 1]` and only then scaled to
95	/// degrees, exactly as the C++ does. The redundant `/6` followed by `*360` is
96	/// observable: it rounds twice, and `adjustSaturation` divides by 360 again and
97	/// amplifies the difference by up to `6*(q-p)`.
98	#[inline]
99	fn hue_degrees(c: &RGB, max: f32, d: f32) -> f32 {
100	    hue_sector(c, max, d) / 6.0 * 360.0
101	}
102	
103	
104	fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
105	    if t < 0.0 {
106	        t += 1.0;
107	    }
108	    if t > 1.0 {
109	        t -= 1.0;
110	    }
111	    if t < 1.0 / 6.0 {
112	        return p + (q - p) * 6.0 * t;
113	    }
114	    if t < 1.0 / 2.0 {
115	        return q;
116	    }
117	    if t < 2.0 / 3.0 {
118	        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
119	    }
120	    p
121	}
