125	impl ColorConverter {
126	    pub fn rgb_to_hsl(c: RGB) -> HSL {
127	        let max = max3(c.r, c.g, c.b);
128	        let min = min3(c.r, c.g, c.b);
129	        let l = (max + min) / 2.0;
130	
131	        if max == min {
132	            return HSL::new(0.0, 0.0, l);
133	        }
134	
135	        let d = max - min;
136	        let s = if l > 0.5 {
137	            d / (2.0 - max - min)
138	        } else {
139	            d / (max + min)
140	        };
141	        let h = hue_degrees(&c, max, d);
142	        HSL::new(h, s, l)
143	    }
144	
145	    pub fn hsl_to_rgb(c: HSL) -> RGB {
146	        let h = c.h / 360.0;
147	        let s = c.s;
148	        let l = c.l;
149	
150	        if s == 0.0 {
151	            return RGB::new(l, l, l);
152	        }
153	
154	        let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
155	        let p = 2.0 * l - q;
156	
157	        RGB::new(
158	            hue_to_rgb(p, q, h + 1.0 / 3.0),
159	            hue_to_rgb(p, q, h),
160	            hue_to_rgb(p, q, h - 1.0 / 3.0),
161	        )
162	    }
163	
164	    pub fn rgb_to_hsv(c: RGB) -> HSV {
165	        let max = max3(c.r, c.g, c.b);
166	        let min = min3(c.r, c.g, c.b);
167	        let d = max - min;
168	
169	        let v = max;
170	        let s = if max == 0.0 { 0.0 } else { d / max };
171	        let h = if max == min {
172	            0.0
173	        } else {
174	            hue_degrees(&c, max, d)
175	        };
176	        HSV::new(h, s, v)
177	    }
178	
179	    pub fn rgb_to_cmyk(c: RGB) -> CMYK {
180	        let k = 1.0 - max3(c.r, c.g, c.b);
181	        if k == 1.0 {
182	            return CMYK::new(0.0, 0.0, 0.0, k);
183	        }
184	        CMYK::new(
185	            (1.0 - c.r - k) / (1.0 - k),
186	            (1.0 - c.g - k) / (1.0 - k),
187	            (1.0 - c.b - k) / (1.0 - k),
188	            k,
189	        )
190	    }
191	
192	    pub fn rgb_to_yuv(c: RGB) -> YUV {
193	        // `u` and `v` contain subtractions, which the compiler cannot commute,
194	        // so there the running accumulator keeps its NaN.
195	        let y = sum3(0.299 * c.r, 0.587 * c.g, 0.114 * c.b);
196	        let u = add_keep_lhs_nan(-0.147 * c.r - 0.289 * c.g, 0.436 * c.b);
197	        let v = 0.615 * c.r - 0.515 * c.g - 0.100 * c.b;
198	        YUV::new(y, u, v)
199	    }
