201	    pub fn adjust_brightness(c: RGB, factor: f32) -> RGB {
202	        RGB::new(
203	            clamp01(c.r * factor),
204	            clamp01(c.g * factor),
205	            clamp01(c.b * factor),
206	        )
207	    }
