209	    pub fn adjust_saturation(c: RGB, factor: f32) -> RGB {
210	        let mut hsl = Self::rgb_to_hsl(c);
211	        hsl.s = clamp01(hsl.s * factor);
212	        Self::hsl_to_rgb(hsl)
213	    }
