215	    pub fn grayscale(c: RGB) -> RGB {
216	        let gray = sum3(0.2126 * c.r, 0.7152 * c.g, 0.0722 * c.b);
217	        RGB::new(gray, gray, gray)
218	    }
219	
220	    pub fn invert(c: RGB) -> RGB {
221	        RGB::new(1.0 - c.r, 1.0 - c.g, 1.0 - c.b)
222	    }
