224	    pub fn color_distance(a: RGB, b: RGB) -> f32 {
225	        let dr = a.r - b.r;
226	        let dg = a.g - b.g;
227	        let db = a.b - b.b;
228	        sum3(dr * dr, dg * dg, db * db).sqrt()
229	    }
