1	//! Reproduction of `std::ostream`'s default floating-point formatting.
2	//!
3	//! `std::cout << some_float` promotes the `float` to `double` and then formats
4	//! it exactly like `printf("%g")` with the default stream precision of 6, i.e.
5	//! six *significant* digits, trailing zeros stripped, and a switch to
6	//! scientific notation when the decimal exponent leaves `[-4, 6)`.
7	
8	/// Default `std::ios_base::precision()`.
9	const PRECISION: i32 = 6;
10	
11	/// Format an `f32` the way `std::cout << value` would (via promotion to
12	/// `double`).
13	pub fn float_to_string(v: f32) -> String {
14	    double_to_string(v as f64)
15	}
16	
17	/// Format an `f64` the way `std::cout << value` would.
18	pub fn double_to_string(v: f64) -> String {
19	    if v.is_nan() {
20	        // glibc prints the sign bit of a NaN, and so does libstdc++.
21	        return if v.is_sign_negative() {
22	            String::from("-nan")
23	        } else {
24	            String::from("nan")
25	        };
26	    }
27	    if v.is_infinite() {
28	        return if v.is_sign_negative() {
29	            String::from("-inf")
30	        } else {
31	            String::from("inf")
32	        };
33	    }
34	
35	    // C99 %g: let X be the exponent of the value converted in style `e` with
36	    // precision P-1. Style `f` is used when -4 <= X < P, otherwise style `e`.
37	    let sci = format!("{:.*e}", (PRECISION - 1) as usize, v);
38	    let e_pos = sci.find('e').expect("exponential form always has an 'e'");
39	    let exp: i32 = sci[e_pos + 1..]
40	        .parse()
41	        .expect("exponent is always a decimal integer");
42	
43	    if exp < -4 || exp >= PRECISION {
44	        let mantissa = strip_trailing_zeros(&sci[..e_pos]);
45	        let sign = if exp < 0 { '-' } else { '+' };
46	        // The exponent always carries a sign and at least two digits.
47	        format!("{}e{}{:02}", mantissa, sign, exp.unsigned_abs())
48	    } else {
49	        let fixed = format!("{:.*}", (PRECISION - 1 - exp) as usize, v);
50	        strip_trailing_zeros(&fixed).to_string()
51	    }
52	}
53	
54	/// Drop the trailing zeros (and then a bare trailing point) of a decimal
55	/// fraction, as `%g` does without the `#` flag.
56	fn strip_trailing_zeros(s: &str) -> &str {
57	    if !s.contains('.') {
58	        return s;
59	    }
60	    let s = s.trim_end_matches('0');
61	    s.strip_suffix('.').unwrap_or(s)
62	}
